package main

import (
	"sort"
)

// Merge merges overlapping or touching intervals and returns them sorted by start.
func Merge(intervals [][]int) [][]int {
	if len(intervals) == 0 {
		return [][]int{}
	}

	// Sort intervals by start time
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0]
	})

	merged := make([][]int, 0)
	merged = append(merged, intervals[0])

	for i := 1; i < len(intervals); i++ {
		current := intervals[i]
		lastMerged := &merged[len(merged)-1]

		// If the current interval's start is less than or equal to 
		// the last merged interval's end, they overlap or touch.
		if current[0] <= lastMerged[1] {
			// Update the end of the last merged interval if the current one is larger
			if current[1] > lastMerged[1] {
				lastMerged[1] = current[1]
			}
		} else {
			// No overlap, add the current interval as a new entry
			merged = append(merged, current)
		}
	}

	return merged
}
