// ParseKV parses a string of key=value pairs.
// It ignores blank lines, comments (starting with #), and lines without an '='.
// Keys and values are trimmed of surrounding whitespace.
// Later duplicate keys override earlier ones.
func ParseKV(text string) map[string]string {
	result := make(map[string]string)
	scanner := bufio.NewScanner(strings.NewReader(text))

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())

		// Ignore blank lines and comments
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Find the first occurrence of '='
		index := strings.Index(line, "=")
		if index == -1 {
			continue
		}

		// Split into key and value based on the first '='
		key := strings.TrimSpace(line[:index])
		value := strings.TrimSpace(line[index+1:])

		// Only add if the key is not empty after trimming
		if key != "" {
			result[key] = value
		}
	}

	return result
}
