pub fn merge(mut intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return Vec::new();
    }

    // Sort intervals by start time
    intervals.sort_unstable_by_key(|interval| interval[0]);

    let mut merged: Vec<Vec<i32>> = Vec::new();

    // Initialize with the first interval
    let mut current_interval = intervals[0].clone();

    for i in 1..intervals.len() {
        let next_interval = &intervals[i];

        // If the current interval's end is greater than or equal to 
        // the next interval's start, they overlap or touch.
        if current_interval[1] >= next_interval[0] {
            // Update the end of the current interval to the maximum end found
            if next_interval[1] > current_interval[1] {
                current_interval[1] = next_interval[1];
            }
        } else {
            // No overlap, push the finished interval and move to the next
            merged.push(current_interval);
            current_interval = next_interval.clone();
        }
    }

    // Push the final interval
    merged.push(current_interval);

    merged
}
