use std::collections::HashMap;

/// Parses a string of key=value pairs into a HashMap.
/// 
/// - Trims whitespace from both keys and values.
/// - Ignores blank lines.
/// - Ignores lines starting with '#' (after optional leading whitespace).
/// - Ignores lines that do not contain an '=' character.
/// - Later duplicate keys override earlier ones.
pub fn parse_kv(text: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();

    for line in text.lines() {
        let trimmed = line.trim();

        // Ignore blank lines and comments
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        // Find the first occurrence of '='
        if let Some(pos) = trimmed.find('=') {
            let key_part = &trimmed[..pos];
            let value_part = &trimmed[pos + 1..];

            let key = key_part.trim().to_string();
            let value = value_part.trim().to_string();

            // Only insert if the key is not empty after trimming
            if !key.is_empty() {
                map.insert(key, value);
            }
        }
    }

    map
}
