```go
package main

// Merge merges overlapping or touching intervals and returns them sorted by start time.
// An empty input returns an empty slice.
func Merge(intervals [][]int) [][]int {
	if len(intervals) == 0 {
		return [][]int{}
	}

	// Sort intervals by start time
	for i := 0; i < len(intervals)-1; i++ {
		for j := 0; j < len(intervals)-i-1; j++ {
			if intervals[j][0] > intervals[j+1][0] {
				intervals[j], intervals[j+1] = intervals[j+1], intervals[j]
			}
		}
	}

	result := make([][]int, 0, len(intervals))
	currentStart := intervals[0][0]
	currentEnd := intervals[0][1]

	for i := 1; i < len(intervals); i++ {
		nextStart := intervals[i][0]
		nextEnd := intervals[i][1]

		if nextStart <= currentEnd {
			// Overlapping or touching, merge them
			if nextEnd > currentEnd {
				currentEnd = nextEnd
			}
		} else {
			// No overlap, push the current merged interval and start a new one
			result = append(result, []int{currentStart, currentEnd})
			currentStart = nextStart
			currentEnd = nextEnd
		}
	}

	// Append the last interval
	result = append(result, []int{currentStart, currentEnd})

	return result
}
