// ParseKV parses a text string where each line contains a key=value pair.
// It trims spaces around keys and values, ignores blank lines, comments (starting with #),
// and lines without '='. Later duplicate keys override earlier ones.
func ParseKV(text string) map[string]string {
	result := make(map[string]string)

	lines := strings.Split(text, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)

		// Ignore blank lines
		if len(line) == 0 {
			continue
		}

		// Ignore comment lines (first non-space character is #)
		if line[0] == '#' {
			continue
		}

		// Ignore lines without '='
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])

		// Skip if key is empty after trimming
		if len(key) == 0 {
			continue
		}

		result[key] = value
	}

	return result
}
