pub fn merge(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return vec![];
    }

    // Sort intervals by start time, then by end time
    let mut sorted_intervals = intervals;
    sorted_intervals.sort_by(|a, b| {
        match a[0].cmp(&b[0]) {
            std::cmp::Ordering::Equal => a[1].cmp(&b[1]),
            other => other,
        }
    });

    let mut merged = Vec::new();
    let mut current_start = sorted_intervals[0][0];
    let mut current_end = sorted_intervals[0][1];

    for interval in sorted_intervals.into_iter().skip(1) {
        let start = interval[0];
        let end = interval[1];

        if start <= current_end {
            // Overlapping or touching intervals, merge them
            current_end = current_end.max(end);
        } else {
            // Non-overlapping interval, push the previous merged interval and start a new one
            merged.push(vec![current_start, current_end]);
            current_start = start;
            current_end = end;
        }
    }

    // Push the last interval
    merged.push(vec![current_start, current_end]);

    merged
}
