use std::collections::HashMap;

pub fn parse_kv(text: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();

    for line in text.lines() {
        // Trim leading and trailing whitespace from the entire line first
        let trimmed_line = line.trim();

        // Ignore blank lines
        if trimmed_line.is_empty() {
            continue;
        }

        // Ignore comment lines (first non-space character is #)
        if trimmed_line.starts_with('#') {
            continue;
        }

        // Ignore lines without '='
        if !trimmed_line.contains('=') {
            continue;
        }

        // Split on the first '=' only to handle values containing '='
        let (key_part, value_part) = trimmed_line.split_once('=').unwrap_or_else(|| panic!("Line missing '=': {}", trimmed_line));

        // Trim spaces around key and value
        let key = key_part.trim().to_string();
        let value = value_part.trim().to_string();

        // Insert into map (later duplicates override earlier ones)
        map.insert(key, value);
    }

    map
}
