function Merge-Interval {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [object[]]$Intervals
    )

    # Sort intervals by start time, then by end time if starts are equal
    $sorted = @($Intervals) | Sort-Object -Property @{Expression = { $_[0] }; Property = 'Start' }, @{Expression = { $_[1] }; Property = 'End' }

    if (-not $sorted.Count) {
        return ''
    }

    # Initialize the first interval
    $currentStart = $sorted[0][0]
    $currentEnd = $sorted[0][1]
    $mergedIntervals = @()

    foreach ($interval in $sorted[1..($sorted.Count - 1)]) {
        $nextStart = $interval[0]
        $nextEnd = $interval[1]

        # Check for overlap or touching (currentEnd >= nextStart)
        if ($currentEnd -ge $nextStart) {
            # Merge: extend the current end if necessary
            if ($nextEnd -gt $currentEnd) {
                $currentEnd = $nextEnd
            }
        }
        else {
            # No overlap, push the current interval and start a new one
            $mergedIntervals += [pscustomobject]@{ Start = $currentStart; End = $currentEnd }
            $currentStart = $nextStart
            $currentEnd = $nextEnd
        }
    }

    # Add the last accumulated interval
    $mergedIntervals += [pscustomobject]@{ Start = $currentStart; End = $currentEnd }

    # Format output as a single string with "start-end" per line
    return ($mergedIntervals | ForEach-Object { "{0}-{1}" -f $_.Start, $_.End }) -join "`n"
}
