package main

import "sort"

// Merge merges overlapping or touching [start, end] intervals and returns them sorted by start.
// An empty input returns an empty slice.
func Merge(intervals [][]int) [][]int {
	if len(intervals) == 0 {
		return [][]int{}
	}

	// Sort intervals by their start time
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0]
	})

	merged := make([][]int, 0, len(intervals))
	// Initialize with the first interval
	current := intervals[0]

	for i := 1; i < len(intervals); i++ {
		next := intervals[i]

		// If the current interval's end is greater than or equal to the next interval's start,
		// they are overlapping or touching.
		if current[1] >= next[0] {
			// Update the end of the current interval to the maximum end value seen so far
			if next[1] > current[1] {
				current[1] = next[1]
			}
		} else {
			// No overlap, push the current interval and move to the next
			merged = append(merged, current)
			current = next
		}
	}

	// Push the last interval
	merged = append(merged, current)

	return merged
}
