// ParseKV parses a string where each line is key=value.
// It trims spaces around keys and values.
// It ignores blank lines, lines starting with # (after whitespace), and lines without '='.
// Later duplicate keys override earlier ones.
func ParseKV(text string) map[string]string {
	result := make(map[string]string)
	scanner := bufio.NewScanner(strings.NewReader(text))

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())

		// Ignore blank lines and comments
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Find the first '=' to split key and value
		index := strings.Index(line, "=")
		if index == -1 {
			continue
		}

		key := strings.TrimSpace(line[:index])
		value := strings.TrimSpace(line[index+1:])

		// Only add if key is not empty (optional, depending on strictness, 
		// but usually '=' implies an empty key or value is valid)
		result[key] = value
	}

	return result
}
