pub fn merge(mut intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return Vec::new();
    }

    // Sort intervals by their start values
    intervals.sort_unstable_by_key(|interval| interval[0]);

    let mut merged: Vec<Vec<i32>> = Vec::with_capacity(intervals.len());

    for interval in intervals {
        // If the list of merged intervals is empty or the current interval 
        // does not overlap with the previous, append it.
        // Note: "Touching" intervals (e.g., [1, 2] and [2, 3]) are merged.
        if merged.is_empty() || merged.last().unwrap()[1] < interval[0] {
            merged.push(interval);
        } else {
            // There is an overlap or they are touching, so merge the current 
            // interval with the last one in the merged list.
            let last = merged.last_mut().unwrap();
            if interval[1] > last[1] {
                last[1] = interval[1];
            }
        }
    }

    merged
}
