use std::collections::HashMap;

/// Parses a string where each line is in the format `key=value`.
/// 
/// Rules:
/// - Trims whitespace around keys and values.
/// - Ignores blank lines.
/// - Ignores lines starting with '#' (after optional whitespace).
/// - Ignores lines without an '=' character.
/// - Later duplicate keys override earlier ones.
pub fn parse_kv(text: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();

    for line in text.lines() {
        let trimmed = line.trim();

        // Ignore blank lines and comments
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        // Split by the first '=' found
        if let Some((key, value)) = trimmed.split_once('=') {
            let k = key.trim().to_string();
            let v = value.trim().to_string();

            // Only insert if the key is not empty (handles cases like "=value")
            // Note: If the requirement implies "=value" is a valid key of empty string,
            // remove the `if !k.is_empty()` check.
            if !k.is_empty() {
                map.insert(k, v);
            }
        }
    }

    map
}
