    foreach ($current in $sorted) {
        # If list is empty or current interval does not overlap/touch the last merged interval
        if ($merged.Count -eq 0 -or $current[0] -gt $merged[-1][1]) {
            $merged.Add($current)
        }
        else {
            # There is an overlap or they touch; merge by updating the end of the last interval
            $last = $merged[-1]
            $newEnd = [Math]::Max($last[1], $current[1])
            $last[1] = $newEnd
        }
    }

    # 2. Format as "start-end" strings
    foreach ($m in $merged) {
        "$($m[0])-$($m[1])"
    }
}
