            if (-not $trimmedLine.Contains('=')) {
                continue
            }

            # 5. Split by the first '=' found to handle values containing '='
            $parts = $trimmedLine -split '=', 2

            # 6. Trim spaces around keys and values
            $key = $parts[0].Trim()
            $value = $parts[1].Trim()

            # 7. Add to hashtable (later duplicate keys automatically override earlier ones)
