pub fn merge(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return vec![];
    }

    let mut sorted = intervals;
    sorted.sort_by(|a, b| a[0].cmp(&b[0]));

    let mut result: Vec<Vec<i32>> = Vec::new();
    let mut current_start = sorted[0][0];
    let mut current_end = sorted[0][1];

    for interval in &sorted[1..] {
        let start = interval[0];
        let end = interval[1];

        if start <= current_end {
            // Overlapping or touching intervals, merge them
            if end > current_end {
                current_end = end;
            }
        } else {
            // Non-overlapping, push the current merged interval and start a new one
            result.push(vec![current_start, current_end]);
            current_start = start;
            current_end = end;
        }
    }

    // Push the last merged interval
    result.push(vec![current_start, current_end]);

    result
}
