pub fn merge(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return Vec::new();
    }

    let mut sorted_intervals = intervals;
    sorted_intervals.sort_by(|a, b| a[0].cmp(&b[0]));

    let mut merged: Vec<Vec<i32>> = Vec::new();
    let mut current = sorted_intervals[0].clone();

    for interval in sorted_intervals.into_iter().skip(1) {
        if interval[0] <= current[1] {
            // Overlapping or touching intervals: merge them
            current[1] = current[1].max(interval[1]);
        } else {
            // Non-overlapping: push current and start new
            merged.push(current);
            current = interval;
        }
    }

    merged.push(current);
    merged
}
