package main

import (
	"sort"
)

// Merge merges overlapping or touching intervals and returns them sorted by start.
func Merge(intervals [][]int) [][]int {
	if len(intervals) == 0 {
		return [][]int{}
	}

	// Sort intervals by their start value
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0]
	})

	merged := [][]int{intervals[0]}
	for i := 1; i < len(intervals); i++ {
		last := merged[len(merged)-1]
		current := intervals[i]

		// Check if the current interval overlaps or touches the last merged interval
		if current[0] <= last[1] {
			// Merge the intervals
			if current[1] > last[1] {
				last[1] = current[1]
			}
		} else {
			// No overlap, add the current interval to the merged list
			merged = append(merged, current)
		}
	}

	return merged
}
