// Each line in the input string should be in the format "key=value".
// Leading and trailing spaces around keys and values are trimmed.
// Blank lines, lines starting with '#' after trimming spaces, and lines without '=' are ignored.
// If a key appears more than once, the last value for that key is used.
func ParseKV(text string) map[string]string {
	result := make(map[string]string)
	lines := strings.Split(text, "\n")

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if idx := strings.Index(line, "="); idx != -1 {
			key := strings.TrimSpace(line[:idx])
			value := strings.TrimSpace(line[idx+1:])
			result[key] = value
		}
	}

	return result
}
