		}
		// Find the first '=' to split key and value
		idx := strings.Index(trimmed, "=")
		if idx == -1 {
			// No '=' found, skip line
			continue
		}
		key := strings.TrimSpace(trimmed[:idx])
		value := strings.TrimSpace(trimmed[idx+1:])
		// Only add if key is not empty after trimming
		if key != "" {
			result[key] = value
		}
	}
	return result
