```rust
/// Merges overlapping or touching intervals and returns them sorted by start.
///
/// An interval [start, end] is considered touching another if `end >= other.start`.
/// The input intervals are not required to be sorted; the output will be sorted by start.
///
/// # Examples
///
/// ```
/// use merge_intervals::merge;
///
/// let input = vec![vec![1, 3], vec![2, 6], vec![8, 10], vec![15, 18]];
/// let output = merge(input);
/// assert_eq!(output, vec![vec![1, 6], vec![8, 10], vec![15, 18]]);
/// ```
pub fn merge(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return Vec::new();
    }

    // Sort intervals by their start value.
    let mut sorted = intervals;
    sorted.sort_by_key(|interval| interval[0]);

    let mut merged: Vec<Vec<i32>> = Vec::new();
    merged.push(sorted[0].clone());

    for current in sorted.iter().skip(1) {
        let last = merged.last_mut().unwrap();
        // If the current interval overlaps or touches the last merged interval,
        // merge them by extending the end to the maximum of both ends.
        if current[0] <= last[1] {
            if current[1] > last[1] {
                last[1] = current[1];
            }
        } else {
            // No overlap; add the current interval as a new entry.
            merged.push(current.clone());
        }
    }

    merged
}
