pub fn merge(intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if intervals.is_empty() {
        return vec![];
    }

    let mut sorted_intervals = intervals;
    sorted_intervals.sort_by_key(|interval| interval[0]);

    let mut merged = vec![sorted_intervals[0].clone()];

    for current in sorted_intervals.iter().skip(1) {
        let last = merged.last_mut().unwrap();

        if current[0] <= last[1] {
            // Overlapping or touching intervals - merge them
            last[1] = last[1].max(current[1]);
        } else {
            // Non-overlapping interval - add it to the result
            merged.push(current.clone());
        }
    }

    merged
