package main

import (
	"sort"
)

// Merge takes a slice of intervals represented as [start, end] pairs,
// merges all overlapping or touching intervals, and returns the
// resulting intervals sorted by their start value.
//
// An empty input returns an empty slice.
func Merge(intervals [][]int) [][]int {
	if len(intervals) == 0 {
		return [][]int{}
	}

	// Sort intervals by start value.
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0]
	})

	merged := make([][]int, 0, len(intervals))
	current := intervals[0]

	for _, iv := range intervals[1:] {
		// If the current interval overlaps or touches the next one,
		// extend the current interval's end if necessary.
		if iv[0] <= current[1]+1 {
			if iv[1] > current[1] {
				current[1] = iv[1]
			}
		} else {
			// No overlap; push the current interval and start a new one.
			merged = append(merged, current)
			current = iv
		}
	}

	// Append the last interval.
	merged = append(merged, current)

	return merged
}
