// ParseKV parses a string containing key=value pairs separated by newlines.
// Lines that are empty, start with a '#' after trimming leading spaces, or
// do not contain an '=' character are ignored. Leading and trailing spaces
// around keys and values are trimmed. If a key appears multiple times,
// the last value wins.
func ParseKV(text string) map[string]string {
	result := make(map[string]string)

	lines := strings.Split(text, "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		// Skip empty lines and comments
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Find the first '='
		idx := strings.Index(trimmed, "=")
		if idx == -1 {
			continue // no key=value pair
		}

		key := strings.TrimSpace(trimmed[:idx])
		value := strings.TrimSpace(trimmed[idx+1:])

		// Skip if key is empty (e.g., "=value")
		if key == "" {
			continue
		}

		result[key] = value
	}

	return result
}
