```rust
/// Merges overlapping or touching intervals.
///
/// # Arguments
///
/// * `intervals` - A vector of intervals, each represented as a two‑element vector `[start, end]`.
///
/// # Returns
///
/// A new vector containing the merged intervals, sorted by their start values.
///
/// # Examples
///
/// ```
/// let input = vec![vec![1, 3], vec![2, 6], vec![8, 10], vec![15, 18]];
/// let merged = merge(input);
/// assert_eq!(merged, vec![vec![1, 6], vec![8, 10], vec![15, 18]]);
/// ```
///
/// An empty input returns an empty vector.
///
/// ```
/// let empty: Vec<Vec<i32>> = Vec::new();
/// assert!(merge(empty).is_empty());
/// ```
pub fn merge(mut intervals: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    // Return early if there are no intervals.
    if intervals.is_empty() {
        return Vec::new();
    }

    // Sort intervals by their start value.
    intervals.sort_by_key(|interval| interval[0]);

    let mut merged: Vec<Vec<i32>> = Vec::new();

    for interval in intervals {
        // If merged is empty or the current interval does not overlap/touch the last one,
        // simply push it onto the result.
        if merged.is_empty() || interval[0] > merged.last().unwrap()[1] + 1 {
            merged.push(interval);
        } else {
            // Otherwise, merge with the last interval by extending its end if necessary.
            let last = merged.last_mut().unwrap();
            if interval[1] > last[1] {
                last[1] = interval[1];
            }
        }
    }

    merged
}
