use std::collections::HashMap;

/// Parses a string containing key/value pairs separated by `=` on each line.
///
/// # Rules
/// * Leading and trailing whitespace around keys and values is removed.
/// * Blank lines, lines that start with `#` (after trimming leading whitespace),
///   and lines that do not contain an `=` are ignored.
/// * If a key appears multiple times, the last value wins.
///
/// # Examples
/// ```
/// let input = "  foo = bar \n# comment\nbaz=qux\nfoo=override\n";
/// let map = parse_kv(input);
/// assert_eq!(map.get("foo"), Some(&"override".to_string()));
/// assert_eq!(map.get("baz"), Some(&"qux".to_string()));
/// ```
pub fn parse_kv(text: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();

    for line in text.lines() {
        // Trim leading/trailing whitespace
        let trimmed = line.trim();

        // Skip empty lines
        if trimmed.is_empty() {
            continue;
        }

        // Skip comments (lines starting with '#')
        if trimmed.starts_with('#') {
            continue;
        }

        // Find the first '='
        if let Some(idx) = trimmed.find('=') {
            let key = trimmed[..idx].trim().to_string();
            let value = trimmed[idx + 1..].trim().to_string();
            // Insert or overwrite the key
            map.insert(key, value);
        }
    }

    map
}
